#!/bin/bash
# DOFEK rant v3. vo/take3.wav is the master clock; every talking shot was
# generated by wan2_7 from the slice of that take it speaks, so frame 0 of a
# shot is the first sample of its slice. Cut points are absolute FRAME numbers
# derived from the audio, so rounding never accumulates. Face shots are cut
# away from on their internal pauses, because this model keeps the mouth
# moving through silence and a held face shot shows it.
set -e
R=/tmp/claude-0/-home-user-SHOPIFY/06af39bb-792a-5cc6-a4be-ecbf44972499/scratchpad/rant
A=/tmp/claude-0/-home-user-SHOPIFY/06af39bb-792a-5cc6-a4be-ecbf44972499/scratchpad/anim/clips
cd $R; S=seg3; rm -rf $S; mkdir -p $S
V="scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,fps=24,setsar=1"
sg () { ffmpeg -y -loglevel error -ss $2 -i $1 -vf "$V" -frames:v $3 -an \
  -c:v libx264 -crf 18 -preset veryfast -pix_fmt yuv420p $S/$4.mp4; }
# slow push-in, non-accumulating form (z=min(k*zoom,..) silently does nothing)
sgz () { ffmpeg -y -loglevel error -ss $2 -i $1 \
  -vf "$V,zoompan=z='1+0.00085*on':d=1:x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':s=1080x1920:fps=24,setsar=1" \
  -frames:v $3 -an -c:v libx264 -crf 18 -preset veryfast -pix_fmt yuv420p $S/$4.mp4; }
#   source      in     frames  out      film in-out     what
sg  cl/X1.mp4   0        55    p01   #   0.00- 2.29  hook, tight
sgz cl/X2.mp4   0       113    p02   #   2.29- 7.00  wide, pointing, slow push
sg  cl/X3.mp4   0        96    p03   #   7.00-11.00  brace, foot on block
sg  $A/c12.mp4  0.5      29    p04   #  11.00-12.21  dial macro on "מגן הברך של דופק"
sg  $A/c10.mp4  0.35     53    p05   #  12.21-14.42  "ולחזור ללכת כמו בן אדם"
sg  $A/c02.mp4  0.60     37    p06   #  14.42-15.96  "לא כמו חיה פצועה"
sg  $A/c01.mp4  0.45     68    p07   #  15.96-18.79  "לא נמאס לך ללכת לעבודה ולסבול"
sg  $A/c03.mp4  0.30     55    p08   #  18.79-21.08  sidelined while the young one works
sg  $A/c05.mp4  0.30     55    p09   #  21.08-23.38  a one-minute walk is an event
sgz cl/X4.mp4   0        84    p10   #  23.38-26.88  "די די כבר", slow push
sg  cl/X5.mp4   0        29    p11   #  26.88-28.09  "רוצה פתרון"
sg  $A/c07.mp4  0.40     27    p12   #  28.09-29.21  the button, on "תלחץ פה"
sg  cl/X5.mp4   2.3125   32    p13   #  29.21-30.54  "...ובוא נגמור את זה באחריות"
sg  cl/X6.mp4   0        63    p14   #  30.54-33.17  warm close
ffmpeg -y -loglevel error -framerate 24 -i t/endseq/f%04d.png -vf "fps=24,setsar=1" -frames:v 65 -an \
  -c:v libx264 -crf 18 -preset veryfast -pix_fmt yuv420p $S/p15.mp4
cd $S; : > list.txt
for f in p01 p02 p03 p04 p05 p06 p07 p08 p09 p10 p11 p12 p13 p14 p15; do echo "file '$f.mp4'" >> list.txt; done
ffmpeg -y -loglevel error -f concat -safe 0 -i list.txt -c copy ../base3.mp4
cd ..; echo -n "base frames: "; ffprobe -v error -count_frames -show_entries stream=nb_read_frames -of csv=p=0 base3.mp4
